class Solution {
    public String finalString(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == 'i') {
                sb.reverse();
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public String finalString(String s) {
        Deque<Character> deque = new ArrayDeque<>();
        boolean front = false;
        for (char c : s.toCharArray()) {
            if (c == 'i') {
                front = !front;
            } else {
                if (front) {
                    deque.addFirst(c);
                } else {
                    deque.addLast(c);
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        if (front) {
            while (!deque.isEmpty()) sb.append(deque.pollLast());
        } else {
            while (!deque.isEmpty()) sb.append(deque.pollFirst());
        }
        return sb.toString();
    }
}
